create table public.clubs(id bigint generated by default as identity primary key,name text not null,slug text not null unique,password_hash text not null,active boolean not null default true,created_at timestamptz not null default now());
create table public.slots(id bigint generated by default as identity primary key,club_id bigint not null references public.clubs(id) on delete cascade,weekday smallint not null check(weekday between 1 and 7),time time not null,label text default '');
create table public.responses(id bigint generated by default as identity primary key,club_id bigint not null references public.clubs(id) on delete cascade,name text not null,no_need boolean not null default false,created_at timestamptz not null default now());
create table public.response_slots(response_id bigint not null references public.responses(id) on delete cascade,slot_id bigint not null references public.slots(id) on delete cascade,primary key(response_id,slot_id));
create index slots_club_idx on public.slots(club_id); create index responses_club_idx on public.responses(club_id);
alter table public.clubs enable row level security; alter table public.slots enable row level security; alter table public.responses enable row level security; alter table public.response_slots enable row level security;
